// 版本 -> 表: 1.21.2+ 用 1.21.2（含苍白花园）；1.20.6~1.21.1 用 1.20；1.19.4~1.20.4 用 1.19.4；1.19.2~1.19.3 用 1.19.2；更早(1.18~1.19.1) 用 1.18
export function tableForVersion(v) {
  const p = String(v).split('.').map(Number); const minor = p[1] || 0, patch = p[2] || 0;
  if (minor >= 22) return '1.21.2';
  if (minor === 21) return patch >= 2 ? '1.21.2' : '1.20';
  if (minor === 20) return patch >= 6 ? '1.20' : '1.19.4';
  if (minor === 19) return patch >= 4 ? '1.19.4' : patch >= 2 ? '1.19.2' : '1.18';
  return '1.18';
}

